const body = $input.first().json.body || $input.first().json;
const lead = body.lead || body;
const bookingUrl = body.booking_url || 'https://meetings-ap1.hubspot.com/christopher-sparshott';
const fallbackThankYou = body.thank_you_message || `Thanks for reaching out to SuccessByCS. Book time with Chris here: ${bookingUrl}`;
const intent = String(body.lead_intent || lead.lead_intent || '').trim();
const intentLabels = {
  browse_directory: 'Browse the vendor directory',
  advisory_follow_up: 'Advisory follow-up with SuccessByCS',
  advisory: 'Advisory follow-up with SuccessByCS',
  shortlist: 'Shortlist brief',
};
const intentLabel = intentLabels[intent] || (intent || 'Lead capture');
const discordWebhook = String(body.discord_webhook_url || $env.DISCORD_WEBHOOK_URL || '').trim();
const discordWebhookUrl = discordWebhook ? (discordWebhook.includes('?') ? `${discordWebhook}&wait=true` : `${discordWebhook}?wait=true`) : '';
const discordContent = body.discord_content || [
  'New CSP lead captured',
  `Lead: ${lead.lead_name || body.lead_name || 'Unknown lead'}`,
  `Company: ${lead.company_name || body.company_name || 'Unknown company'}`,
  `Email: ${lead.lead_email || body.lead_email || ''}`,
  `Intent: ${intentLabel}`,
  `Book time with Chris: ${bookingUrl}`,
].join('\n');
return [{ json: { lead_id: lead.lead_id || body.lead_id || '', lead_intent: intent, intent_label: intentLabel, thank_you_message: fallbackThankYou, booking_url: bookingUrl, discord_webhook_url: discordWebhookUrl, discord_content: discordContent } }];
